{
  "name": "@bakalarka/dunning-system",
  "version": "1.0.0",
  "description": "Automated billing reminder state machine for escalating unpaid invoices",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "dunning",
    "billing",
    "state-machine",
    "invoice",
    "payment"
  ],
  "license": "MIT",
  "devDependencies": {
    "typescript": "^5.3.0",
    "vitest": "^1.2.0"
  }
}

function toLocalDateString(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

function isHoliday(date: Date, holidays: Set<string>): boolean {
  return holidays.has(toLocalDateString(date));
}

export function isBusinessDay(date: Date, holidays: Date[] = []): boolean {
  const holidaySet = new Set(holidays.map((h) => toLocalDateString(h)));
  return !isWeekend(date) && !isHoliday(date, holidaySet);
}

export function addBusinessDays(
  startDate: Date,
  days: number,
  holidays: Date[] = []
): Date {
  const holidaySet = new Set(holidays.map((h) => toLocalDateString(h)));
  const current = new Date(startDate);

  if (days === 0) {
    return current;
  }

  if (days > 0) {
    let remaining = days;
    while (remaining > 0) {
      current.setDate(current.getDate() + 1);
      const key = toLocalDateString(current);
      if (!isWeekend(current) && !holidaySet.has(key)) {
        remaining--;
      }
    }
  } else {
    let remaining = Math.abs(days);
    while (remaining >= 0) {
      const key = toLocalDateString(current);
      if (!isWeekend(current) && !holidaySet.has(key)) {
        remaining--;
        if (remaining < 0) break;
      }
      current.setDate(current.getDate() - 1);
    }
  }

  return current;
}

export function businessDaysBetween(
  startDate: Date,
  endDate: Date,
  holidays: Date[] = []
): number {
  const holidaySet = new Set(holidays.map((h) => toLocalDateString(h)));
  const start = new Date(startDate);
  const end = new Date(endDate);

  if (end <= start) {
    return 0;
  }

  let count = 0;
  const current = new Date(start);

  while (current < end) {
    current.setDate(current.getDate() + 1);
    const key = toLocalDateString(current);
    if (!isWeekend(current) && !holidaySet.has(key)) {
      count++;
    }
  }

  return count;
}

export function getTargetDate(
  startDate: Date,
  businessDays: number,
  holidays: Date[] = []
): Date {
  return addBusinessDays(startDate, businessDays, holidays);
}

import type {
  DunningStatus,
  DunningEvent,
  DunningState,
  DunningConfig,
  ProcessResult,
  ActionDescriptor,
} from "./types.js";
import { businessDaysBetween } from "./businessDays.js";

const DEFAULT_TIMEOUTS: Record<DunningStatus, number> = {
  ISSUED: 0,
  DUE_SOON: 7,
  OVERDUE: 3,
  GRACE: 7,
  REMINDER_1: 14,
  REMINDER_2: 14,
  FINAL_NOTICE: 7,
  SUSPENDED: 30,
  WRITTEN_OFF: 0,
  PAID: 0,
  PAUSED: 0,
  CANCELLED: 0,
};

const ACTIVE_STATES: DunningStatus[] = [
  "OVERDUE",
  "GRACE",
  "REMINDER_1",
  "REMINDER_2",
  "FINAL_NOTICE",
  "SUSPENDED",
];

const TERMINAL_STATES: DunningStatus[] = ["WRITTEN_OFF", "PAID", "CANCELLED"];

const ESCALATION_ORDER: DunningStatus[] = [
  "ISSUED",
  "DUE_SOON",
  "OVERDUE",
  "GRACE",
  "REMINDER_1",
  "REMINDER_2",
  "FINAL_NOTICE",
  "SUSPENDED",
  "WRITTEN_OFF",
];

function mergeConfig(config?: Partial<DunningConfig>): DunningConfig {
  return {
    timeouts: config?.timeouts
      ? { ...DEFAULT_TIMEOUTS, ...config.timeouts }
      : DEFAULT_TIMEOUTS,
    holidays: config?.holidays ?? [],
  };
}

function getTimeout(
  status: DunningStatus,
  config: DunningConfig
): number {
  return config.timeouts?.[status] ?? DEFAULT_TIMEOUTS[status];
}

function isActiveState(status: DunningStatus): boolean {
  return ACTIVE_STATES.includes(status);
}

function isTerminalState(status: DunningStatus): boolean {
  return TERMINAL_STATES.includes(status);
}

function getNextState(currentStatus: DunningStatus): DunningStatus | null {
  const currentIndex = ESCALATION_ORDER.indexOf(currentStatus);
  if (currentIndex === -1 || currentIndex >= ESCALATION_ORDER.length - 1) {
    return null;
  }
  return ESCALATION_ORDER[currentIndex + 1];
}

function getActionsForTransition(
  _fromStatus: DunningStatus,
  toStatus: DunningStatus
): ActionDescriptor[] {
  const actions: ActionDescriptor[] = [];

  switch (toStatus) {
    case "DUE_SOON":
      actions.push({ type: "send_email", template: "due_soon_reminder" });
      break;
    case "REMINDER_1":
      actions.push({ type: "send_email", template: "first_reminder" });
      break;
    case "REMINDER_2":
      actions.push({ type: "send_email", template: "second_reminder" });
      break;
    case "FINAL_NOTICE":
      actions.push({ type: "send_email", template: "final_warning" });
      break;
    case "SUSPENDED":
      actions.push({ type: "suspend_service" });
      actions.push({ type: "send_email", template: "service_suspended" });
      break;
    case "WRITTEN_OFF":
      actions.push({ type: "send_email", template: "written_off_notice" });
      break;
  }

  return actions;
}

function calculateBusinessDaysElapsed(
  stateEnteredAt: Date,
  now: Date,
  holidays: Date[]
): number {
  return businessDaysBetween(stateEnteredAt, now, holidays);
}

export function createInstance(
  dueDate: Date,
  config?: Partial<DunningConfig>
): DunningState {
  return {
    status: "ISSUED",
    dueDate: new Date(dueDate),
    stateEnteredAt: new Date(),
    config: mergeConfig(config),
  };
}

export function process(
  state: DunningState,
  event: DunningEvent,
  now: Date
): ProcessResult {
  const { status, config, stateEnteredAt, pausedFrom, pausedElapsed } = state;

  if (isTerminalState(status)) {
    return { state, actions: [] };
  }

  switch (event.type) {
    case "tick": {
      const holidays = config.holidays ?? [];
      const dueDate = state.dueDate;

      if (status === "ISSUED") {
        const businessDaysLeft = businessDaysBetween(now, dueDate, holidays);
        if (businessDaysLeft === getTimeout("DUE_SOON", config)) {
          return {
            state: {
              ...state,
              status: "DUE_SOON",
              stateEnteredAt: now,
            },
            actions: getActionsForTransition("ISSUED", "DUE_SOON"),
          };
        }
      }

      if (status === "DUE_SOON") {
        if (now >= new Date(dueDate)) {
          return {
            state: {
              ...state,
              status: "OVERDUE",
              stateEnteredAt: now,
            },
            actions: [],
          };
        }
      }

      if (status === "OVERDUE" || status === "GRACE") {
        const effectiveElapsed =
          pausedElapsed ??
          calculateBusinessDaysElapsed(stateEnteredAt, now, holidays);
        const timeout = getTimeout(status, config);

        if (effectiveElapsed >= timeout) {
          const nextStatus = getNextState(status);
          if (nextStatus) {
            return {
              state: {
                ...state,
                status: nextStatus,
                stateEnteredAt: now,
              },
              actions: getActionsForTransition(status, nextStatus),
            };
          }
        }
      }

      if (
        status === "REMINDER_1" ||
        status === "REMINDER_2" ||
        status === "FINAL_NOTICE" ||
        status === "SUSPENDED"
      ) {
        const effectiveElapsed =
          pausedElapsed ??
          calculateBusinessDaysElapsed(stateEnteredAt, now, holidays);
        const timeout = getTimeout(status, config);

        if (effectiveElapsed >= timeout) {
          const nextStatus = getNextState(status);
          if (nextStatus) {
            return {
              state: {
                ...state,
                status: nextStatus,
                stateEnteredAt: now,
              },
              actions: getActionsForTransition(status, nextStatus),
            };
          }
        }
      }

      return { state, actions: [] };
    }

    case "payment_received": {
      const actions: ActionDescriptor[] = [];

      if (status === "SUSPENDED") {
        actions.push({ type: "resume_service" });
      }

      return {
        state: {
          ...state,
          status: "PAID",
          stateEnteredAt: now,
        },
        actions,
      };
    }

    case "invoice_cancelled": {
      const actions: ActionDescriptor[] = [];

      if (status === "SUSPENDED") {
        actions.push({ type: "resume_service" });
      }

      return {
        state: {
          ...state,
          status: "CANCELLED",
          stateEnteredAt: now,
        },
        actions,
      };
    }

    case "dunning_paused": {
      if (!isActiveState(status)) {
        return { state, actions: [] };
      }

      const elapsed = calculateBusinessDaysElapsed(
        stateEnteredAt,
        now,
        config.holidays ?? []
      );

      return {
        state: {
          ...state,
          status: "PAUSED",
          pausedFrom: status,
          pausedElapsed: elapsed,
          stateEnteredAt: now,
        },
        actions: [],
      };
    }

    case "dunning_resumed": {
      if (status !== "PAUSED" || !pausedFrom) {
        return { state, actions: [] };
      }

      return {
        state: {
          ...state,
          status: pausedFrom,
          pausedFrom: undefined,
          pausedElapsed: undefined,
          stateEnteredAt: now,
        },
        actions: [],
      };
    }

    case "manual_advance": {
      if (!isActiveState(status) || isTerminalState(status)) {
        return { state, actions: [] };
      }

      const nextStatus = getNextState(status);
      if (!nextStatus) {
        return { state, actions: [] };
      }

      return {
        state: {
          ...state,
          status: nextStatus,
          stateEnteredAt: now,
        },
        actions: getActionsForTransition(status, nextStatus),
      };
    }

    default:
      return { state, actions: [] };
  }
}

export type DunningStatus =
  | "ISSUED"
  | "DUE_SOON"
  | "OVERDUE"
  | "GRACE"
  | "REMINDER_1"
  | "REMINDER_2"
  | "FINAL_NOTICE"
  | "SUSPENDED"
  | "WRITTEN_OFF"
  | "PAID"
  | "PAUSED"
  | "CANCELLED";

export type EventType =
  | "tick"
  | "payment_received"
  | "invoice_cancelled"
  | "dunning_paused"
  | "dunning_resumed"
  | "manual_advance";

export interface DunningEvent {
  type: EventType;
}

export type ActionType = "send_email" | "suspend_service" | "resume_service";

export interface ActionDescriptor {
  type: ActionType;
  template?: string;
}

export interface DunningConfig {
  timeouts?: Partial<Record<DunningStatus, number>>;
  holidays?: Date[];
}

export interface DunningState {
  status: DunningStatus;
  dueDate: Date;
  stateEnteredAt: Date;
  config: DunningConfig;
  pausedFrom?: DunningStatus;
  pausedElapsed?: number;
}

export interface ProcessResult {
  state: DunningState;
  actions: ActionDescriptor[];
}

import { describe, it, expect } from "vitest";
import {
  isBusinessDay,
  addBusinessDays,
  businessDaysBetween,
  getTargetDate,
} from "../src/businessDays";

describe("Business Days", () => {
  describe("isBusinessDay", () => {
    it("should return true for Monday", () => {
      const monday = new Date("2024-11-04");
      expect(isBusinessDay(monday)).toBe(true);
    });

    it("should return false for Saturday", () => {
      const saturday = new Date("2024-11-02");
      expect(isBusinessDay(saturday)).toBe(false);
    });

    it("should return false for Sunday", () => {
      const sunday = new Date("2024-11-03");
      expect(isBusinessDay(sunday)).toBe(false);
    });

    it("should exclude custom holidays", () => {
      const christmas = new Date("2024-12-25");
      expect(isBusinessDay(christmas, [christmas])).toBe(false);
    });

    it("should include regular weekdays", () => {
      const tuesday = new Date("2024-11-05");
      const wednesday = new Date("2024-11-06");
      const thursday = new Date("2024-11-07");
      const friday = new Date("2024-11-08");

      expect(isBusinessDay(tuesday)).toBe(true);
      expect(isBusinessDay(wednesday)).toBe(true);
      expect(isBusinessDay(thursday)).toBe(true);
      expect(isBusinessDay(friday)).toBe(true);
    });
  });

  describe("addBusinessDays", () => {
    it("should add 0 days to Friday and return Friday", () => {
      const friday = new Date("2024-11-01");
      const result = addBusinessDays(friday, 0);
      expect(result.getDay()).toBe(5);
    });

    it("should add 1 business day from Friday to Monday", () => {
      const friday = new Date("2024-11-01");
      const result = addBusinessDays(friday, 1);
      expect(result.getDay()).toBe(1);
    });

    it("should add 14 business days starting Friday excluding weekend", () => {
      const friday = new Date("2024-11-01");
      const result = addBusinessDays(friday, 14);

      const startKey = friday.toISOString().split("T")[0];
      const endKey = result.toISOString().split("T")[0];

      let businessDays = 0;
      const current = new Date(friday);
      while (current < result) {
        current.setDate(current.getDate() + 1);
        if (current.getDay() !== 0 && current.getDay() !== 6) {
          businessDays++;
        }
      }

      expect(businessDays).toBe(14);
    });

    it("should exclude holidays from count", () => {
      const friday = new Date("2024-11-01");
      const holiday = new Date("2024-11-04");
      const result = addBusinessDays(friday, 1, [holiday]);

      expect(result.getDay()).toBe(2);
    });

    it("should handle negative days for subtracting business days", () => {
      const monday = new Date("2024-11-04");
      const result = addBusinessDays(monday, -2);
      expect(result.getDay()).toBe(4);
    });
  });

  describe("businessDaysBetween", () => {
    it("should return 0 for same date", () => {
      const monday = new Date("2024-11-04");
      expect(businessDaysBetween(monday, monday)).toBe(0);
    });

    it("should return 1 business day from Friday to Monday", () => {
      const friday = new Date("2024-11-01");
      const monday = new Date("2024-11-04");
      expect(businessDaysBetween(friday, monday)).toBe(1);
    });

    it("should exclude weekends", () => {
      const wednesday = new Date("2024-11-06");
      const nextWednesday = new Date("2024-11-13");
      expect(businessDaysBetween(wednesday, nextWednesday)).toBe(5);
    });

    it("should exclude holidays from count", () => {
      const monday = new Date("2024-11-04");
      const tuesday = new Date("2024-11-05");
      const holiday = new Date("2024-11-04");
      expect(businessDaysBetween(monday, tuesday, [holiday])).toBe(1);
    });

    it("should return 0 when end is before start", () => {
      const monday = new Date("2024-11-04");
      const friday = new Date("2024-11-01");
      expect(businessDaysBetween(monday, friday)).toBe(0);
    });
  });

  describe("getTargetDate", () => {
    it("should return same date for 0 business days", () => {
      const friday = new Date("2024-11-01");
      const result = getTargetDate(friday, 0);
      expect(dateToYMD(result)).toBe(dateToYMD(friday));
    });

    it("should calculate correct target date for 7 business days", () => {
      const friday = new Date("2024-11-01");
      const result = getTargetDate(friday, 7);

      let businessDays = 0;
      const current = new Date(friday);
      while (current < result) {
        current.setDate(current.getDate() + 1);
        if (current.getDay() !== 0 && current.getDay() !== 6) {
          businessDays++;
        }
      }

      expect(businessDays).toBe(7);
    });

    it("should handle custom holidays in target date calculation", () => {
      const friday = new Date("2024-11-01");
      const mondayHoliday = new Date("2024-11-04");
      const result = getTargetDate(friday, 1, [mondayHoliday]);

      expect(result.getDay()).toBe(2);
    });
  });
});

function dateToYMD(date: Date): string {
  return date.toISOString().split("T")[0];
}

import { describe, it, expect, beforeEach } from "vitest";
import { createInstance, process } from "../src/dunning.js";
import type { DunningEvent, DunningState } from "../src/types.js";
import { addBusinessDays as bdAddBusinessDays } from "../src/businessDays.js";

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function addBusinessDays(date: Date, days: number): Date {
  return bdAddBusinessDays(date, days);
}

describe("Dunning System", () => {
  describe("createInstance", () => {
