  describe("Invoice cancellation", () => {
    it("should transition to CANCELLED from non-terminal states", () => {
      const dueDate = new Date("2024-12-01");
      const activeStates: DunningState["status"][] = [
        "ISSUED",
        "DUE_SOON",
