function toLocalDateString(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return \`\${year}-\${month}-\${day}\`;
}

function isWeekend(date) {
  const day = date.getDay();
  return day === 0 || day === 6;
}

function businessDaysBetween(startDate, endDate, holidays = []) {
  const holidaySet = new Set(holidays.map((h) => toLocalDateString(h)));
  const start = new Date(startDate);
  const end = new Date(endDate);

  if (end <= start) {
    return 0;
  }

  let count = 0;
  const current = new Date(start);

  while (current < end) {
    current.setDate(current.getDate() + 1);
    const key = toLocalDateString(current);
    if (!isWeekend(current) && !holidaySet.has(key)) {
      count++;
    }
  }

  return count;
}

function addBusinessDays(startDate, days, holidays = []) {
  const holidaySet = new Set(holidays.map((h) => toLocalDateString(h)));
  const current = new Date(startDate);

  if (days === 0) {
    return current;
  }

  if (days > 0) {
    let remaining = days;
    while (remaining > 0) {
      current.setDate(current.getDate() + 1);
      const key = toLocalDateString(current);
      if (!isWeekend(current) && !holidaySet.has(key)) {
        remaining--;
      }
    }
  } else {
    let remaining = Math.abs(days);
    while (remaining > 0) {
      current.setDate(current.getDate() - 1);
      const key = toLocalDateString(current);
      if (!isWeekend(current) && !holidaySet.has(key)) {
        remaining--;
      }
    }
  }

  return current;
}

