      if (!nextStatus) {
        return { state, actions: [] };
      }

      return {
        state: {
          ...state,
          status: nextStatus,
          stateEnteredAt: now,
        },
        actions: getActionsForTransition(status, nextStatus),
      };
    }

    default:
      return { state, actions: [] };
  }
}

