                ...state,
                status: nextStatus,
                stateEnteredAt: now,
              },
              actions: getActionsForTransition(status, nextStatus),
            };
          }
        }
      }

      return { state, actions: [] };
    }

    case "payment_received": {
      const actions: ActionDescriptor[] = [];

      if (status === "SUSPENDED") {
        actions.push({ type: "resume_service" });
      }

      return {
        state: {
          ...state,
          status: "PAID",
          stateEnteredAt: now,
        },
        actions,
      };
    }

    case "invoice_cancelled": {
      const actions: ActionDescriptor[] = [];

      if (status === "SUSPENDED") {
        actions.push({ type: "resume_service" });
      }

      return {
        state: {
          ...state,
          status: "CANCELLED",
          stateEnteredAt: now,
        },
        actions,
      };
    }

    case "dunning_paused": {
      if (!isActiveState(status)) {
        return { state, actions: [] };
      }

      const elapsed = calculateBusinessDaysElapsed(
        stateEnteredAt,
        now,
        config.holidays ?? []
      );

      return {
        state: {
          ...state,
          status: "PAUSED",
          pausedFrom: status,
          pausedElapsed: elapsed,
          stateEnteredAt: now,
        },
        actions: [],
      };
    }

    case "dunning_resumed": {
      if (status !== "PAUSED" || !pausedFrom) {
        return { state, actions: [] };
      }

      return {
        state: {
          ...state,
          status: pausedFrom,
          pausedFrom: undefined,
          pausedElapsed: undefined,
          stateEnteredAt: now,
        },
        actions: [],
      };
    }

    case "manual_advance": {
      if (!isActiveState(status) || isTerminalState(status)) {
        return { state, actions: [] };
      }

      const nextStatus = getNextState(status);
      if (!nextStatus) {
        return { state, actions: [] };
      }

      return {
        state: {
          ...state,
          status: nextStatus,
          stateEnteredAt: now,
        },
        actions: getActionsForTransition(status, nextStatus),
      };
    }

    default:
      return { state, actions: [] };
  }
}

