              state: {
                ...state,
                status: nextStatus,
                stateEnteredAt: now,
              },
              actions: getActionsForTransition(status, nextStatus),
            };
          }
        }
      }

      if (
        status === "REMINDER_1" ||
        status === "REMINDER_2" ||
        status === "FINAL_NOTICE" ||
        status === "SUSPENDED"
      ) {
        const effectiveElapsed =
          pausedElapsed ??
